// Generated by Suite Builder from a crawl of the site. The jira command: jira login, pull, push, typed in the suite's folder.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Your Jira names go in jira-loop/jira.properties (jira login fills them in).
// The suite's jira command (G-214), typed in its folder (cmd: jira; PowerShell: .\jira; Mac and Linux: ./jira):
//   jira login      connect: the address, the account and its token, the project and its statuses, chosen
//   jira pull       the stories waiting in the watched statuses, into stories/new/
//   jira push       what the crew decided, shown, then sent: a comment on each card, the card moved on
//   jira status     who is signed in, and what is waiting; changes nothing
//   jira flags      the four statuses the loop uses: ready, claimed, BA triage, done
//   jira watch      which statuses mark a story as ready to pull (also: jira --setWatchflag)
//   jira claim      where a card goes as it is pulled, so no one else takes it (also: jira --setClaimflag)
//   jira output     where a card goes once the crew has had a go (also: jira --setOutputflag)
//   jira logout     the token forgotten on this computer
// Dashes and the word "stories" are optional: jira --pull stories is jira pull. The work is
// jira-loop/sync.mjs's, which the pipeline runs on its own; this asks the person, and shows before it sends.
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ask, bold, choose, cyan, dim, tty } from '../menu/keys.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SYNC = join(ROOT, 'jira-loop', 'sync.mjs');
const SETTINGS = join(ROOT, 'jira-loop', 'jira.properties');
const ACCOUNT = join(ROOT, 'secrets', 'jira.login');
const BLANK = 'Username:\nPassword:\n';

/** jira-loop/sync.mjs, its output shown as it comes: its exit code. */
function sync(args) {
  return spawnSync(process.execPath, [SYNC, ...args], { cwd: ROOT, stdio: 'inherit' }).status ?? 1;
}

/** jira-loop/sync.mjs's one line of JSON, or null with its reason said. `env`: an account not yet saved. */
function syncJson(args, env = {}) {
  const run = spawnSync(process.execPath, [SYNC, ...args], { cwd: ROOT, encoding: 'utf8', env: { ...process.env, ...env } });
  if (run.status === 0) return JSON.parse(run.stdout);
  console.log(`  ${(run.stderr || run.stdout).trim()}`);
  return null;
}

/** The settings as written: name to value. */
function settings() {
  const s = {};
  if (!existsSync(SETTINGS)) return s;
  for (const line of readFileSync(SETTINGS, 'utf8').split(/\r?\n/)) {
    const m = /^\s*([a-z]+)\s*=\s*(.*?)\s*$/.exec(line);
    if (m && !line.trimStart().startsWith('#')) s[m[1]] = m[2];
  }
  return s;
}

/** Each value set in place in jira-loop/jira.properties: the team's comments and order kept. */
function setSettings(values) {
  let text = existsSync(SETTINGS) ? readFileSync(SETTINGS, 'utf8') : '';
  for (const [name, value] of Object.entries(values)) {
    const line = new RegExp(`^(\\s*${name}\\s*=).*$`, 'm');
    text = line.test(text) ? text.replace(line, `$1 ${value}`) : `${text.trimEnd()}\n${name} = ${value}\n`;
  }
  writeFileSync(SETTINGS, text);
}

/** Whether this computer can sign in: a token saved here, or the environment's. */
function connected() {
  const saved = existsSync(ACCOUNT) && /^Password:\s*\S/m.test(readFileSync(ACCOUNT, 'utf8'));
  return Boolean(settings().site) && (saved || Boolean(process.env.JIRA_API_TOKEN));
}

function needsPerson(what) {
  if (tty) return false;
  console.log(`jira ${what} asks its questions at a terminal: type it in the suite's folder.`);
  return true;
}

/** Several statuses as written: "Ready for QA Development, Ready for QA". */
const list = (value) => (value ?? '').split(',').map((v) => v.trim()).filter(Boolean);

/** The statuses that mark a story ready to pull, ticked from the project's own (the watch flag). */
async function pickWatched(names, current) {
  console.log(`\n  ${bold('Which statuses mean a story is ready for the suite to pull?')}\n`);
  const ticked = names.map((n, i) => (current.some((c) => c.toLowerCase() === n.toLowerCase()) ? i : -1)).filter((i) => i >= 0);
  const picked = await choose(names.map((n) => ({ label: n, what: 'A card a BA moves here is pulled into stories/new/ by jira pull (and by the pipeline).' })), { multi: true, ticked, at: ticked[0] ?? 0, esc: 'to stop' });
  return picked && picked.map((i) => names[i]);
}

const NO_CLAIM = 'Leave the card where it is (no claimed status)';

/** Where a card goes as it is pulled (the claimed flag): a status of the project's, or none. */
async function pickClaimed(names, current) {
  console.log(`\n  ${bold('Where does a card go when the suite takes it?')}\n  ${dim('So no one else takes it, and the board shows it is being worked on. Your Jira admin may need to add such a status.')}\n`);
  const options = [NO_CLAIM, ...names];
  const at = Math.max(0, options.findIndex((n) => n.toLowerCase() === (current ?? '').toLowerCase()));
  const i = await choose(options.map((n) => ({ label: n, what: n === NO_CLAIM ? 'jira pull leaves the card in its ready status.' : 'jira pull moves the card here as it takes the story; jira push moves it on from here.' })), { at, esc: 'to stop' });
  return i === null ? null : i === 0 ? '' : options[i];
}

/** Where a card goes once the crew has had a go: all of it tested, or pushed back (the output flags). */
async function pickOutput(names, s) {
  const one = async (question, what, current) => {
    console.log(`\n  ${bold(question)}\n`);
    const at = Math.max(0, names.findIndex((n) => n.toLowerCase() === (current ?? '').toLowerCase()));
    const i = await choose(names.map((n) => ({ label: n, what })), { at, esc: 'to stop' });
    return i === null ? null : names[i];
  };
  const implemented = await one('Where does a card go when every criterion has a test?', 'jira push moves it here, with a comment naming the tests.', s.implemented);
  if (!implemented) return null;
  const triage = await one('Where does a card go when the crew pushes it back, or a criterion waits on an answer?', 'jira push moves it here, with the questions as a comment; the same status as the first is fine.', s.triage);
  return triage && { implemented, triage };
}

/** jira login: connected, and every name chosen from Jira's own lists; the token kept in secrets/jira.login. */
async function login() {
  if (needsPerson('login')) return 1;
  const s = settings();
  console.log(`\n  ${bold('Connect this suite to Jira')}\n  ${dim('Asked once. The token is kept in secrets/jira.login: never committed, blank in every pack.')}\n`);
  const typed = await ask(`Your Jira's address${s.site ? ` (Enter for ${s.site})` : ' (e.g. your-company.atlassian.net)'}`) || s.site;
  if (!typed) return 0;
  const site = (/^https?:\/\//i.test(typed) ? typed : `https://${typed}`).replace(/(\.atlassian\.net)\/.*$/i, '$1').replace(/\/+$/, '');
  const edition = /\.atlassian\.net$/i.test(new URL(site).hostname) ? 'cloud' : 'data-center';
  const email = edition === 'cloud' ? await ask('The email you sign in to Jira with') : '';
  if (edition === 'cloud' && !email) return 0;
  console.log(dim(edition === 'cloud'
    ? '  A token: https://id.atlassian.com/manage-profile/security/api-tokens, "Create API token", then paste it here.'
    : '  A token: in Jira, your picture, Profile, Personal Access Tokens, "Create token", then paste it here.'));
  const token = await ask('The token', { hidden: true });
  if (!token) return 0;
  const env = { JIRA_SITE: site, JIRA_EDITION: edition, JIRA_EMAIL: email, JIRA_API_TOKEN: token };
  const found = syncJson(['projects'], env);
  if (!found) return 1;
  console.log(`  Signed in as ${found.me}.`);
  if (found.projects.length === 0) {
    console.log('  This account sees no project: ask your Jira admin to give it access to the stories\' project.');
    return 1;
  }
  console.log(`\n  ${bold('Which project holds the stories?')}\n`);
  const at = Math.max(0, found.projects.findIndex((p) => p.key === s.project));
  const p = await choose(found.projects.map((x) => ({ label: `${x.key}  ${x.name}`, what: 'The project whose stories this suite turns into tests.' })), { at, esc: 'to stop' });
  if (p === null) return 0;
  const project = found.projects[p].key;
  const names = syncJson(['statuses', project], env);
  if (!names) return 1;
  const watched = await pickWatched(names, list(s.ready));
  if (!watched) return 0;
  const claimed = await pickClaimed(names, s.claimed);
  if (claimed === null) return 0;
  const output = await pickOutput(names, s);
  if (!output) return 0;
  mkdirSync(dirname(ACCOUNT), { recursive: true });
  writeFileSync(ACCOUNT, `Username: ${email}\nPassword: ${token}\n`);
  setSettings({ site, edition, project, ready: watched.join(', '), claimed, ...output });
  console.log(`\n  ${bold('Connected.')} Saved in jira-loop/jira.properties (commit it: it holds no secret).\n`);
  sync(['check']);
  console.log(`\n  Next: ${cyan('jira pull')} brings the ready stories in. To run it without you, see the stories pipeline file's top.`);
  return 0;
}

/** jira watch / jira output: one setting chosen again from the project's statuses. */
async function rechoose(which) {
  if (needsPerson(which)) return 1;
  if (!connected()) return notConnected();
  const s = settings();
  const names = syncJson(['statuses', s.project]);
  if (!names) return 1;
  const values = which === 'watch' ? await pickWatched(names, list(s.ready)) : which === 'claim' ? await pickClaimed(names, s.claimed) : await pickOutput(names, s);
  if (values === null) return 0;
  setSettings(which === 'watch' ? { ready: values.join(', ') } : which === 'claim' ? { claimed: values } : values);
  console.log('\n  Saved in jira-loop/jira.properties.');
  return flags();
}

/** jira push: what each card will get, shown; sent when the person says so (or --yes, for a script). */
async function push(yes) {
  if (!connected()) return notConnected();
  const pending = syncJson(['pending']);
  if (!pending) return 1;
  if (pending.length === 0) {
    console.log('Nothing to send: no story has a new outcome (jira pull, then Claude Code\'s /stories, first).');
    return 0;
  }
  console.log(`\n  ${bold(`${pending.length} ${pending.length === 1 ? 'card' : 'cards'} to update in Jira`)}\n`);
  for (const p of pending) {
    console.log(`  ${bold(p.key)}  ${p.done ? 'tested' : 'pushed back'}: moves to "${p.to}", with this comment:`);
    console.log(p.note.split('\n').slice(0, 8).map((l) => `      ${dim(l)}`).join('\n'));
    if (p.note.split('\n').length > 8) console.log(`      ${dim(`... the rest in stories/${p.done ? 'done' : 'new'}/${p.file}`)}`);
  }
  console.log('');
  if (!yes) {
    if (!tty) {
      console.log('Not sent: jira push --yes sends without asking.');
      return 1;
    }
    const go = await choose([{ label: 'Send them to Jira', what: 'Each card gets its comment and moves; the BA sees it.' }, { label: 'Not now', what: 'Nothing is sent; jira push shows them again.' }], { esc: 'to stop' });
    if (go !== 0) return 0;
  }
  return sync(['report']);
}

function logout() {
  if (existsSync(ACCOUNT)) writeFileSync(ACCOUNT, BLANK);
  console.log('The Jira token is forgotten on this computer (secrets/jira.login is blank). jira login connects again.');
  return 0;
}

function notConnected() {
  console.log(`This suite is not connected to Jira on this computer: ${cyan('jira login')} connects it (a few questions, once).`);
  return 1;
}

/** jira flags: the four statuses the loop uses, as set. */
function flags() {
  const s = settings();
  const said = (v, none = '(not set)') => (v ? `"${v}"` : none).padEnd(26);
  console.log(`${bold('The four flags')} (statuses in ${s.project || 'the project'}):
  1. ${'Ready'.padEnd(11)}${said(list(s.ready).join('" or "'))}${dim('the BA moves a story here; jira pull takes it')}
  2. ${'Claimed'.padEnd(11)}${said(s.claimed, '(none)')}${dim(s.claimed ? 'jira pull moves it here as it takes it' : 'jira pull leaves the card where it is')}
  3. ${'BA Triage'.padEnd(11)}${said(s.triage)}${dim('jira push: pushed back, or waiting on an answer')}
  4. ${'Done'.padEnd(11)}${said(s.implemented)}${dim('jira push: every criterion has a test')}
Change them: jira watch (1), jira claim (2), jira output (3 and 4).`);
  return 0;
}

/** jira --help: where things stand, the next step, every command and what it does, and the four flags as set. */
function help() {
  const s = settings();
  const on = connected();
  const step = !on ? `${cyan('jira login')} connects this suite to Jira: a few questions, once.`
    : `${cyan('jira pull')} brings the ready stories in; then the crew (type ${cyan('crew')}, "Turn the new stories into tests"); then ${cyan('jira push')}.`;
  const row = (cmd, what) => `  ${cyan(cmd.padEnd(31))}${what}`;
  console.log(`
${bold('jira: the suite and your Jira, connected')}  ${on ? `connected to ${s.site}, project ${s.project}` : 'not connected yet on this computer'}

${bold('Next')}  ${step}

${bold('The loop, in the order you use it')}
${row('jira login', 'connect: your Jira\'s address and a token, then the project and the four flags, chosen from lists')}
${row('jira pull', 'bring the stories waiting in the Ready flag into stories/new/; each card moves to Claimed')}
${row('jira push', 'show what each card will get (its comment, where it moves), then send it when you say so')}
${row('jira status', 'who is signed in, what is waiting in Jira, and whether each move is allowed; changes nothing')}

${bold('Settings')}
${row('jira flags', 'the four flags as set (below)')}
${row('jira watch  (--setWatchflag)', 'flag 1: which statuses mean a story is ready to pull')}
${row('jira claim  (--setClaimflag)', 'flag 2: where a card goes as it is pulled, so no one else takes it')}
${row('jira output (--setOutputflag)', 'flags 3 and 4: where a card goes once the crew has had a go')}
${row('jira logout', 'forget the token on this computer')}
${row('jira --help', 'this page')}
`);
  flags();
  console.log(`\nThe whole loop, for the BA too: jira-loop/README.md. Dashes and the word "stories" are optional: jira --pull stories is jira pull.`);
  return 0;
}

const ALIASES = { h: 'help', '?': 'help', setwatchflag: 'watch', setclaimflag: 'claim', setoutputflag: 'output', setflags: 'flags', check: 'status', report: 'push', connect: 'login', signin: 'login', signout: 'logout' };
const words = process.argv.slice(2).map((a) => a.replace(/^-+/, '').toLowerCase()).filter((a) => a && a !== 'stories');
const yes = words.includes('yes') || words.includes('y');
const word = words.find((w) => w !== 'yes' && w !== 'y') ?? 'help';
const command = ALIASES[word] ?? word;
const RUN = {
  login, logout, help, flags, push: () => push(yes), watch: () => rechoose('watch'), claim: () => rechoose('claim'), output: () => rechoose('output'),
  pull: () => (connected() ? sync(['pull']) : notConnected()),
  status: () => (connected() ? sync(['check']) : notConnected()),
};
if (!RUN[command]) {
  console.log(`jira ${word}: no such command.`);
  help();
  process.exitCode = 1;
} else {
  process.exitCode = await RUN[command]();
}
